{"implementation":"def solve(case):
    segments = case['segments']
    if not segments:
        raise ValueError("No segments")
    allocations = [seg['minimum'] for seg in segments]
    total_budget = case['budget']
    sum_min = sum(seg['minimum'] for seg in segments)
    sum_cap = sum(seg['capacity'] for seg in segments)
    if total_budget < sum_min or total_budget > sum_cap:
        raise ValueError("Budget out of feasible range")
    remaining = total_budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                score = seg['importance'] / (allocations[i] + 1.0)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError("Cannot allocate remaining budget")
        allocations[best_idx] += 1
        remaining -= 1
    total = sum(allocations)
    by_name = {seg['name']: allocations[i] for i, seg in enumerate(segments)}
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": total
    }"}
